// Every string the Hotspot Reports tab renders (hotspot-reports NFR-11; QA-01,
// QA-39, QA-72).
//
// The agreement rules are swept over a corpus GENERATED by calling every
// count-bearing builder at 0, 1 and 2 (ui.md v1.0.5): no count of one with a
// plural noun, no determiner with a bare "1", no plural verb after a subject
// counted at one. A ban list of known-bad strings could only reject defects
// someone already found.

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import * as copy from './hotspotReportsCopy'
import { TAB_LABELS } from './tabLayout'

const COUNTS = [0, 1, 2]

/**
 * Every count-bearing string, by calling every builder in the states the tab
 * can REACH (testing.md v1.0.22: per render state, never a free grid). A
 * readable count never exceeds its total, a shown window never reaches its
 * match count, a share is drawn only over at least one checklist that says.
 */
function corpus(): string[] {
  const out: string[] = []
  for (const a of COUNTS) {
    out.push(copy.overviewMeta(a), copy.checklistCountLabel(a), `${a} ${copy.totalLabel(a)}`,
      `${a} ${copy.hotspotFigureLabel(a)}`, `${a} ${copy.personalFigureLabel(a)}`, copy.nothingClassifiedLine(a),
      `${a} ${copy.rankUnit('checklists', a)}`, `${a} ${copy.rankUnit('species', a)}`,
      `${copy.soleChecklistsParts(a).before}Home${copy.soleChecklistsParts(a).after}`,
      `${copy.soleSpeciesParts(a).before}Home${copy.soleSpeciesParts(a).after}`,
      `${copy.TOTAL_LABELS.checklists(a)} ${a}`, copy.COLUMN_HEADERS.of(a), copy.hoursMinutes(a), copy.hoursMinutes(a * 60),
      copy.hoursMinutes(a * 60 + a), `${a} ${copy.biggestLabel(a)}`, copy.earlierYearsLabel(1900 + a),
      `${a}${copy.NOT_YET_KNOWN_TAIL}`, copy.weatherBelowFloor(a + 9), copy.announceOverview(a),
      `${a} ${copy.MEDIA_UNITS.photo(a)}, ${a} ${copy.MEDIA_UNITS.audio(a)}, ${a} ${copy.MEDIA_UNITS.video(a)}`,
      `${a} ${copy.checklistsNoun(a)}`)
  }
  for (const total of [1, 2, 3]) {
    out.push(copy.announceLocation('Home', 0, total), copy.announceLocation('Home', 1, total), copy.announceLocation('Home', 2, total))
    for (let part = 0; part <= total; part++) {
      out.push(`${copy.datedDenominator(part, total).figure}${copy.datedDenominator(part, total).tail}`)
      if (part >= 1) {
        out.push(copy.onChecklistsSr(part, total), `on ${part}${copy.ofChecklistsTail(total)}`, copy.positionPrefix(part, total),
          copy.timeBirdedNote(part, total), `${part}${copy.lifeListCaption(part, total)}`, `${total}${copy.lifeListCaption(total, part)}`)
      }
      for (let more = 0; part + more <= total; more++) {
        if (part + more >= 1) out.push(`${part}${copy.weatherCoverage(part, total, more)}`)
      }
    }
    for (let known = 1; known <= total; known++) {
      for (let complete = 0; complete <= known; complete++) out.push(`50%${copy.completeSentence(complete, known, total - known)}`)
    }
    for (let shown = 0; shown < total; shown++) out.push(copy.narrowingLine(shown, total))
  }
  return out
}

describe('count-bearing sentences agree in number (NFR-11, QA-72)', () => {
  const all = corpus()

  it('the corpus is not vacuous', () => {
    expect(all.length).toBeGreaterThan(150)
  })

  it('no count of one takes a plural noun', () => {
    // "1 species" is correct English; a verb after a count of one is the next
    // row's business, so the noun rule skips the singular verbs ending in s.
    const bad = all.filter(s => /(?:^|[^0-9,.])1 (?!(?:species|does|says|carries|includes|was|is|has)\b)[a-z]+s\b/.test(s))
    expect(bad).toEqual([])
  })

  it('no plural verb follows a subject counted at one, sentence by sentence', () => {
    const PLURAL_VERBS = ['carry', 'say', 'do', 'are', 'include', 'were']
    const bad: string[] = []
    for (const s of all) {
      for (const sentence of s.split(/(?<=\.)\s/)) {
        // The 1 is the SUBJECT's count, not the denominator inside "of your 1".
        // An auxiliary inside the phrase ("1 does not say") is a singular verb
        // already, so the phrase between the count and the verb is nouns only.
        const m = /(?:^|\s)(?<!of (?:your|the) )1 ([a-z]+(?: [a-z]+)?) (carry|say|do|are|include|were)\b/.exec(sentence)
        if (m && !/\b(?:does|not|is|has|was)\b/.test(m[1])) bad.push(sentence)
      }
    }
    expect(PLURAL_VERBS.length).toBe(6)
    expect(bad).toEqual([])
  })

  it('at two, a count takes the plural', () => {
    expect(copy.checklistCountLabel(2)).toBe('2 checklists')
    expect(copy.narrowingLine(200, 2)).toContain('2 locations')
    expect(copy.announceLocation('Home', 2, 2)).toBe('Home: 2 species, 2 checklists.')
    expect(copy.announceLocation('Home', 1, 1)).toBe('Home: 1 species, 1 checklist.')
    expect(copy.announceOverview(1)).toBe('Overview: 1 location.')
    expect(copy.hoursMinutes(90)).toBe('1 hour 30 minutes')
    expect(copy.hoursMinutes(121)).toBe('2 hours 1 minute')
    expect(copy.weatherCoverage(1, 30, 1)).toBe(' of your 30 checklists here carries a weather block SnowRaven can read. 1 more carries a block it could not read.')
    expect(copy.completeSentence(4, 5, 2)).toBe(' complete: 4 of the 5 checklists that say whether every species was reported. 2 do not say.')
  })
})

describe('the tab is named only through TAB_LABELS (QA-01, QA-39)', () => {
  it('the title is the label', () => {
    expect(copy.TAB_TITLE).toBe(TAB_LABELS['hotspot-reports'])
    expect(copy.TAB_TITLE).toBe('Hotspot Reports')
  })

  it('the rule sentence names Life Lists, Statistics and Map Explorer by their labels', () => {
    for (const t of ['life-lists', 'birding-stats', 'map-explorer'] as const) expect(copy.RULE_SENTENCE).toContain(TAB_LABELS[t])
  })

  it('no string in the module names the tab otherwise', () => {
    const strings = Object.values(copy).filter((v): v is string => typeof v === 'string')
    for (const s of strings) expect(/hotspot report/i.test(s) && !s.includes('Hotspot Reports')).toBe(false)
  })
})

describe('copy hygiene (NFR-11, QA-72)', () => {
  const raw = readFileSync(fileURLToPath(new URL('./hotspotReportsCopy.ts', import.meta.url)), 'utf8')
  const code = raw.split('\n').filter(l => !l.trimStart().startsWith('//')).join('\n')

  it('holds no U+2014 and no British spelling of color or center', () => {
    expect(raw.includes('\u2014')).toBe(false)
    for (const s of corpus().concat(Object.values(copy).filter((v): v is string => typeof v === 'string'))) {
      expect(/\b(colour|centre)/i.test(s), s).toBe(false)
      expect(s.includes('\u2014'), s).toBe(false)
    }
  })

  it('holds no literal non-ASCII character in its code; the ellipsis is an escape', () => {
    const bad: number[] = []
    for (let i = 0; i < code.length; i++) if (code.charCodeAt(i) > 0x7e) bad.push(code.charCodeAt(i))
    expect(bad).toEqual([])
    expect(copy.ELLIPSIS).toBe('\u2026')
    expect(copy.displayName('Bolinas', true)).toBe('Bolinas\u2026')
    expect(copy.displayName('', false)).toBe(copy.UNNAMED_LOCATION)
  })

  it('every reason sentence exists and ends as a sentence', () => {
    for (const r of ['no-key', 'checking', 'offline', 'unanswered', 'no-region'] as const) expect(copy.KIND_REASONS[r]).toMatch(/\.$/)
  })
})
